const b = $input.first().json.body || $input.first().json;
const esc = (s) => (s == null || s === '') ? 'NULL' : `'${String(s).replace(/'/g, "''")}'`;
const num = (n) => (n == null || n === '' || isNaN(Number(n))) ? 'NULL' : Number(n);
const lit = (s) => String(s == null ? '' : s).replace(/'/g, "''");
// เก็บ brand ไว้ใน detail ด้วย (การ์ดเครดิต model ว่าง → admin เดา brand จากชื่อรุ่นไม่ได้)
const detailObj = Object.assign({}, b.detail || {}, { brand: b.brand || '' });
const detail = JSON.stringify(detailObj).replace(/'/g, "''");

const insertLead = `INSERT INTO leads (lead_type, model, variant, color, pay_type, down_pct, installment, period, price, cust_name, cust_phone, line_user_id, detail, lang)
VALUES (${esc(b.lead_type)}, ${esc(b.model)}, ${esc(b.variant)}, ${esc(b.color)}, ${esc(b.pay_type)}, ${num(b.down_pct)}, ${num(b.installment)}, ${num(b.period)}, ${num(b.price)}, ${esc(b.cust_name)}, ${esc(b.cust_phone)}, ${esc(b.line_user_id)}, '${detail}'::jsonb, ${esc(b.lang)});`;

// ลูกค้า credit → เข้า customers เพื่อโผล่ใน CRM (เฉพาะเมื่อมี line_user_id จาก LIFF)
const interest = b.model || '';
const dispName = b.line_name || b.cust_name || '';
const uid = lit(b.line_user_id);
let upsertCust = '';
if (uid) {
  upsertCust = `INSERT INTO customers (line_user_id, display_name, phone, interest_model, lead_count, last_seen, updated_at)
VALUES ('${uid}', ${esc(dispName)}, ${esc(b.cust_phone)}, ${esc(interest)}, 1, NOW(), NOW())
ON CONFLICT (line_user_id) DO UPDATE SET
  display_name = COALESCE(customers.display_name, NULLIF(EXCLUDED.display_name, '')),
  phone = COALESCE(NULLIF(EXCLUDED.phone, ''), customers.phone),
  interest_model = COALESCE(NULLIF(EXCLUDED.interest_model, ''), customers.interest_model),
  lead_count = customers.lead_count + 1,
  status = CASE WHEN customers.status IN ('approved','rejected') THEN 'new' ELSE customers.status END,
  assignee = CASE WHEN customers.status IN ('approved','rejected') THEN NULL ELSE customers.assignee END,
  last_seen = NOW(),
  updated_at = NOW();`;
}

return [{ json: { sql: insertLead + '\n' + upsertCust } }];
